uations\n# sx4*a + sx3*b + sx2*c = sx2y\n# sx3*a + sx2*b + sx*c = sxy\n# sx2*a + sx*b + n*c = sy\n\n# Using sympy for verification\nfrom sympy import symbols, solve\n\na, b, c = symbols('a b c')\neq1 = sx4*a + sx3*b + sx2*c - sx2y\neq2 = sx3*a + sx2*b + sx*c - sxy\neq3 = sx2*a + sx*b + n*c - sy\n\nresult = solve([eq1, eq2, eq3], (a, b, c))\nprint(f\"Solution: a={result[a]}, b={result[b]}, c={result[c]}\")\n\n# Calculate prediction for x=7\na_val = float(result[a])\nb_val = float(result[b])\nc_val = float(result[c])\n\ny_pred = a_val*7**2 + b_val*7 + c_val\nprint(f\"\\nPrediction for x=7 (April 1970): {y_pred}\")\nprint(f\"Rounded: {round(y_pred)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
