)\n\n# Inverse elements\nA11i = (A22*A33 - A23*A32) / det\nA12i = -(A12*A33 - A13*A32) / det\nA13i = (A12*A23 - A13*A22) / det\n\nA21i = -(A21*A33 - A23*A31) / det\nA22i = (A11*A33 - A13*A31) / det\nA23i = -(A11*A23 - A13*A21) / det\n\nA31i = (A21*A32 - A22*A31) / det\nA32i = -(A11*A32 - A12*A31) / det\nA33i = (A11*A22 - A12*A21) / det\n\n# beta = inverse(A) * [sum_x2y, sum_xy, sum_y]\na = A11i * sum_x2y + A12i * sum_xy + A13i * sum_y\nb = A21i * sum_x2y + A22i * sum_xy + A23i * sum_y\nc = A31i * sum_x2y + A32i * sum_xy + A33i * sum_y\n\nprint(f\"a = {a}\")\nprint(f\"b = {b}\")\nprint(f\"c = {c}\")\n\n# Predict for x=7\ny_pred = a*7*7 + b*7 + c\nprint(f\"\\nPrediction for x=7: {y_pred}\")\nprint(f\"Rounded: {round(y_pred)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
